<template>
 <section ref="workspace" class="engineering-workspace" :style="{'--input-width':leftWidth+'px','--context-width':rightWidth+'px'}">
  <header class="object-heading" :class="`task-${taskType}`"><div><strong>{{title}}</strong><el-tag v-if="wellLabel" size="small">{{wellLabel}}</el-tag></div><el-radio-group v-if="taskType==='generic'" v-model="mode" size="small"><el-radio-button value="trajectory">轨迹</el-radio-button><el-radio-button value="collision">防碰评价</el-radio-button><el-radio-button value="report">报告设置</el-radio-button></el-radio-group></header>
  <div class="object-toolbar"><div><el-button text icon="DocumentChecked" @click="$emit('save')">保存</el-button><el-button text icon="Edit" @click="$emit('rename')">重命名</el-button><el-button text icon="Clock" @click="$emit('history')">历史</el-button><el-divider direction="vertical"/><el-tag type="info">{{datum||'—'}}</el-tag><el-tag type="info">网格北</el-tag></div><div><el-button text icon="Upload" @click="router.push('/drilling/basic/surveys?tab=sources')">导入</el-button><el-button text icon="Download" :disabled="!hasResult" @click="$emit('export',{format:'bundle',sections:reportSections})">导出报告</el-button><el-button text icon="FullScreen" @click="toggleFullscreen">{{full?'退出全屏':'全屏'}}</el-button></div></div>
