  <div v-else class="workspace-columns" :class="{'with-settings':settingsOpen,'context-hidden':!contextOpen, [`task-${taskType}`]:true}">
   <aside class="input-column"><el-tabs v-model="leftTab" stretch><el-tab-pane label="输入与约束" name="input"><slot name="input"/></el-tab-pane><el-tab-pane label="结果方案" name="solutions"><slot name="solutions"/></el-tab-pane></el-tabs></aside>
   <div class="column-resizer" role="separator" aria-label="调整输入栏宽度" @pointerdown="startResize($event,'left')"/>
