    <div v-if="taskType==='anticollision'&&view==='details'" class="workspace-scroll"><slot name="collision"/></div>
    <div v-else-if="taskType==='anticollision'&&view==='2d'" class="two-projections"><TrajectoryPlot ref="profile" :trajectories="trajectories" view="vertical" :azimuth="azimuth" :hidden="hidden" :markers="markers" :grid="grid" :legend="legend" :risk-segments="riskSegments"/><TrajectoryPlot :trajectories="trajectories" view="horizontal" :hidden="hidden" :markers="markers" :grid="grid" :legend="legend" :risk-segments="riskSegments"/></div>
    <div v-else-if="taskType==='anticollision'" class="plot-region"><TrajectoryPlot ref="scene" :trajectories="trajectories" :azimuth="azimuth" :nearest-pair="nearestPair" :hidden="hidden" :markers="markers" :grid="grid" :legend="legend" :risk-segments="riskSegments"/></div>
    <div v-else-if="view==='table'" class="workspace-scroll"><slot name="table"/></div>
