    <div v-else class="plot-region"><TrajectoryPlot ref="scene" :trajectories="trajectories" :azimuth="azimuth" :nearest-pair="nearestPair" :hidden="hidden" :markers="markers" :grid="grid" :legend="legend" :risk-segments="riskSegments"/></div>
   </main>
