 </section>
</template>
<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import TrajectoryVisibility from './TrajectoryVisibility.vue'
import TrajectoryPlot from '@/components/TrajectoryPlot'
import {riskColors} from '@/utils/trajectoryColors'
const props=defineProps({title:String,wellLabel:String,datum:String,hasResult:Boolean,taskType:{type:String,default:'generic'},trajectories:{type:Array,default:()=>[]},originalTrajectories:{type:Array,default:()=>[]},showOriginal:Boolean,nearestPair:Object,riskSegments:{type:Array,default:()=>[]},riskLabel:String,minimumSf:Number,defaultAzimuth:{type:Number,default:0}})
defineEmits(['save','rename','history','export','refresh']);const router=useRouter(),workspace=ref(),scene=ref(),profile=ref(),contextProfile=ref(),mode=ref(props.taskType==='anticollision'?'collision':'trajectory'),view=ref('3d'),leftTab=ref('input'),settingsOpen=ref(false),contextOpen=ref(true),bottomOpen=ref(true),leftWidth=ref(290),rightWidth=ref(275),markers=ref(true),grid=ref(true),legend=ref(true),hidden=ref([]),azimuth=ref(props.defaultAzimuth),full=ref(false),reportSections=ref(['trajectory','constraints','collision','sources'])
const riskType=computed(()=>({RED:'danger',ORANGE:'warning',YELLOW:'warning',BLUE:'success'}[props.riskLabel]||'info'))
const depths=computed(()=>props.trajectories.flatMap(t=>(t.points||[]).map(p=>Number(p.md)).filter(Number.isFinite)));const minMd=computed(()=>depths.value.length?Math.min(...depths.value):0),maxMd=computed(()=>depths.value.length?Math.max(...depths.value):1),spanMd=computed(()=>Math.max(1,maxMd.value-minMd.value))
function toggleTrajectory(id,yes){hidden.value=yes?hidden.value.filter(x=>x!==id):[...hidden.value,id]}
let detach
function startResize(e,side){e.preventDefault();const x=e.clientX,w=side==='left'?leftWidth.value:rightWidth.value;const move=v=>{const value=Math.min(480,Math.max(220,w+(v.clientX-x)*(side==='left'?1:-1)));if(side==='left')leftWidth.value=value;else rightWidth.value=value};detach=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',detach)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',detach,{once:true})}
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(workspace.value.requestFullscreen)await workspace.value.requestFullscreen();else throw Error('当前浏览器不支持屏幕全屏');full.value=!!document.fullscreenElement}catch(e){ElMessage.warning(e.message)}}
function syncFullscreen(){full.value=!!document.fullscreenElement}
onMounted(()=>document.addEventListener('fullscreenchange',syncFullscreen))
onBeforeUnmount(()=>{detach?.();document.removeEventListener('fullscreenchange',syncFullscreen)});defineExpose({view,mode,leftTab,reportSections})
</script>
